    firststops:{name:'YOUR FIRST STOPS',story:'Twenty very different workplaces ask for a dependable courier. Historic names belong to real buildings, parks and research projects here. Good tools, careful planning and helpful neighbours keep every road open.',accent:'#f2cf87'},
